/* شهادات مؤتة — المحرّك: المعاينة الحية، تطبيق قالب الموضوع، التنزيل والطباعة */
function main(){
'use strict';
const fs=document.createElement('style');fs.id='fontStyles';fs.textContent=FONT_CSS;document.head.appendChild(fs);
const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
if(document.body.dataset.page==='home'){renderHome();return}
const dept=THEMES[document.body.dataset.dept]||THEMES.general;
const defaultsOf=d=>({honorific:'المعلم الفاضل',recipient:'ليث الجعافرة',occasion:d.occasion,reason:d.reason,date:'2026-10-25',deptName:d.name});
let defaults=defaultsOf(dept);
const normalize=t=>t.replace(/[\u0000-\u001f]/g,' ').replace(/\s+/g,' ').trim();
let toastTimer;
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4000)}
function measure(el,text,size){el.setAttribute('font-size',size);el.textContent=text;return el.getComputedTextLength()}
function fit(el,text,maxWidth,startSize,minSize){el.removeAttribute('textLength');el.removeAttribute('lengthAdjust');let size=startSize;const w=measure(el,text,size);if(w>maxWidth)size=Math.max(minSize,size*maxWidth/w);el.setAttribute('font-size',size);if(el.getComputedTextLength()>maxWidth){el.setAttribute('textLength',maxWidth);el.setAttribute('lengthAdjust','spacingAndGlyphs')}return size}
function splitText(el,text,width,size){
 const tokens=text.split(' '),lines=[];let line='';
 for(const token of tokens){const next=line?line+' '+token:token;if(line&&measure(el,next,size)>width){lines.push(line);line=token}else line=next}if(line)lines.push(line);return lines;
}
function linesTo(el,lines,y,leading,size,maxWidth){el.replaceChildren();el.setAttribute('y',y);el.setAttribute('font-size',size);el.removeAttribute('textLength');el.removeAttribute('lengthAdjust');lines.forEach((line,i)=>{const t=document.createElementNS(NS,'tspan');t.setAttribute('x','700');t.setAttribute('dy',i===0?0:leading);t.textContent=line+(i<lines.length-1?' ':'');el.appendChild(t);if(t.getComputedTextLength()>maxWidth){t.setAttribute('textLength',maxWidth);t.setAttribute('lengthAdjust','spacingAndGlyphs')}})}
function recipientName(text){const el=$('recipientText');el.replaceChildren();const width=1040;let size=58;const actual=measure(el,text,size);if(actual<=width){el.setAttribute('y','549');return}size=Math.max(40,58*width/actual);if(measure(el,text,size)<=width){el.setAttribute('y','549');return}const words=text.split(' ');if(words.length<2){fit(el,text,width,40,32);el.setAttribute('y','549');return}let lines=[],score=Infinity;for(let i=1;i<words.length;i++){const a=words.slice(0,i).join(' '),b=words.slice(i).join(' '),wa=measure(el,a,42),wb=measure(el,b,42),value=Math.abs(wa-wb)+Math.max(0,Math.max(wa,wb)-width)*3;if(value<score){score=value;lines=[a,b]}}linesTo(el,lines,530,50,42,width)}
function reasonText(raw){const text=normalize(raw),el=$('reasonText');if(!text){el.replaceChildren();return}let size=23,lines=splitText(el,text,1080,size);while(lines.length>3&&size>18){size-=1;lines=splitText(el,text,1080,size)}if(lines.length>3)lines=[lines[0],lines[1],lines.slice(2).join(' ')];const start=lines.length===1?677:lines.length===2?656:637;linesTo(el,lines,start,38,size,1080)}
function update(){
 paintDept();
 const name=normalize($('recipient').value)||'اسم المُكرَّم';
 $('honorificText').textContent=$('honorific').value;
 recipientName(name);reasonText($('reason').value);
 const occasion=normalize($('occasion').value),occasionEl=$('occasionText');
 occasionEl.setAttribute('class',/[\u0600-\u06ff]/.test(occasion)?'ar':'en');fit(occasionEl,occasion,340,22,14);$('eventGroup').style.display=occasion?'':'none';
 const date=$('date').value;$('dateGroup').style.display=date?'':'none';$('dateText').textContent=date?date.split('-').reverse().join(' / '):'';
 $('reasonCount').textContent=$('reason').value.length+' / 240';
 $('certDesc').textContent='شهادة شكر وتقدير إلى '+name+'، صادرة عن مدرسة مؤتة الثانوية للبنين. مدير المدرسة الدكتور إبراهيم الصرايرة.';
}
Object.keys(defaults).forEach(id=>$(id).addEventListener('input',update));
$('certificateForm').addEventListener('submit',e=>e.preventDefault());
$('resetBtn').addEventListener('click',()=>{for(const [key,value]of Object.entries(defaults))$(key).value=value;update();toast('تمت استعادة البيانات الأصلية.')});
$('printBtn').addEventListener('click',async()=>{await document.fonts.ready;update();window.print()});
$('pngBtn').addEventListener('click',async()=>{
 const btn=$('pngBtn'),label=btn.querySelector('span');btn.disabled=true;label.textContent='جارٍ إعداد الصورة…';let svgUrl;
 try{
 await document.fonts.ready;update();
 const svg=$('certificate').cloneNode(true);svg.querySelector('#svgFontStyles').textContent=FONT_CSS;svg.setAttribute('width','3508');svg.setAttribute('height','2480');
 const source=new XMLSerializer().serializeToString(svg);
 svgUrl=URL.createObjectURL(new Blob([source],{type:'image/svg+xml;charset=utf-8'}));
 const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error('image'));image.src=svgUrl});
 const canvas=document.createElement('canvas');canvas.width=3508;canvas.height=2480;const ctx=canvas.getContext('2d');if(!ctx)throw new Error('canvas');ctx.fillStyle=cur.bg;ctx.fillRect(0,0,3508,2480);ctx.drawImage(image,0,0,3508,2480);
 const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('blob')),'image/png'));
 const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='شهادة_مؤتة_'+(normalize($('recipient').value)||'تكريم').replace(/[\\/:*?"<>|]/g,'_')+'.png';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('تم إعداد الشهادة عالية الدقة للتنزيل.');
 }catch(error){toast('تعذر تنزيل الصورة. يمكنك استخدام الطباعة وحفظ الشهادة بصيغة PDF.');console.error('Certificate export failed:',error)}
 finally{if(svgUrl)URL.revokeObjectURL(svgUrl);btn.disabled=false;label.textContent='تنزيل الشهادة بصيغة PNG'}
});
function paintDept(){
 const n=normalize($('deptName').value),ie=$('introText');
 ie.textContent=n?'يتقدم '+n+' في مدرسة مؤتة الثانوية للبنين بخالص الشكر والتقدير إلى':'تتقدم إدارة مدرسة مؤتة الثانوية للبنين بخالص الشكر والتقدير إلى';
 fit(ie,ie.textContent,1000,22,16);
}
let cur,styleKey='signature',bgIdx=0;
try{styleKey=localStorage.getItem('mutahStyle')||'signature';bgIdx=+(localStorage.getItem('mutahBg_'+dept.key)||0)}catch(e){}
function applyStyle(k,i){
 if(!STYLES[k])k='signature';if(i==null)i=bgIdx;if(!(i>=0&&i<dept.bgs.length))i=0;
 styleKey=k;bgIdx=i;try{localStorage.setItem('mutahStyle',k);localStorage.setItem('mutahBg_'+dept.key,i)}catch(e){}
 cur=buildStyle(dept,k,i);const s=$('certificate');s.style.color=cur.color;
 for(const [x,v] of Object.entries(cur.vars))s.style.setProperty('--'+x,v);
 $('themeArt').innerHTML=cur.art;
 $('styles').innerHTML=Object.entries(STYLES).map(([id,st])=>{const w=buildStyle(dept,id,i).sw;return '<button type="button" class="sty" data-s="'+id+'" aria-pressed="'+(id===k)+'"><i style="background:linear-gradient(135deg,'+w[0]+' 50%,'+w[1]+' 50%)"></i>'+st.label+'</button>'}).join('');
 $('bgs').innerHTML=dept.bgs.map((g,n)=>'<button type="button" class="sty bg" data-b="'+n+'" aria-pressed="'+(n===i)+'" title="'+g.label+'"><i class="num">'+['١','٢','٣'][n]+'</i>'+g.label+'</button>').join('');
 document.querySelectorAll('.sty[data-s]').forEach(b=>b.onclick=()=>applyStyle(b.dataset.s));
 document.querySelectorAll('.sty[data-b]').forEach(b=>b.onclick=()=>applyStyle(styleKey,+b.dataset.b));
}
function applyTheme(){
 const r=document.documentElement.style,ui=dept.ui||dept.accent;
 $('emblemIcon').innerHTML=dept.icon;$('taglineText').textContent=dept.tag;
 $('logoSchool').setAttribute('href',LOGOS.school);$('logoMin').setAttribute('href',LOGOS.ministry);
 r.setProperty('--cyan',ui);
 document.title='شهادات '+(dept.name||dept.label)+' | مدرسة مؤتة';
 $('pageH1').textContent=dept.name?'شهادات '+dept.name:'قالب شهادة عام';$('pageLead').textContent=dept.desc+' — عدّل البيانات وعاين الشهادة مباشرةً.';
 $('depts').innerHTML=Object.values(THEMES).map(t=>'<a class="chip" href="'+t.key+'.html" style="--c:'+(t.ui||t.accent)+'"'+(t.key===dept.key?' aria-current="page"':'')+'><svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true">'+t.icon+'</svg><span>'+t.label+'</span></a>').join('');
 for(const id of ['honorific','occasion','reason','deptName'])$(id).value=defaults[id];
 applyStyle(styleKey);
}
function renderHome(){
 $('cards').innerHTML=Object.values(THEMES).map(t=>'<a class="card" href="'+t.key+'.html" style="--c:'+(t.ui||t.accent)+'"><div class="thumb"><svg viewBox="0 0 1400 990" style="color:'+t.accent+'" aria-hidden="true">'+t.art+'</svg><span class="ico"><svg class="ui-icon" viewBox="0 0 24 24">'+t.icon+'</svg></span></div><div class="meta"><b>'+t.label+'</b><small>'+t.desc+'</small></div></a>').join('');
}
applyTheme();update();document.fonts.ready.then(update);
}

/* الخطوط المضمّنة: Aref Ruqaa للعناوين والأسماء، Cairo للنصوص (تُحقن في الصفحة وفي ملف PNG) */
const FONT_CSS="@font-face{font-family:'MutahDisplay';font-style:normal;font-weight:700;font-display:block;src:url(data:font/woff2;base64,) format('woff2');unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD}@font-face{font-family:'MutahDisplay';font-style:normal;font-weight:700;font-display:block;src:url(data:font/woff2;base64,) format('woff2');unicode-range:U+0600-06FF,U+0750-077F,U+0870-088E,U+0890-0891,U+0897-08E1,U+08E3-08FF,U+200C-200E,U+2010-2011,U+204F,U+2E41,U+FB50-FDFF,U+FE70-FE74,U+FE76-FEFC}@font-face{font-family:'MutahText';font-style:normal;font-weight:400;font-display:block;src:url(data:font/woff2;base64,) format('woff2');unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD}@font-face{font-family:'MutahText';font-style:normal;font-weight:400;font-display:block;src:url(data:font/woff2;base64,) format('woff2');unicode-range:U+0600-06FF,U+0750-077F,U+0870-088E,U+0890-0891,U+0897-08E1,U+08E3-08FF,U+200C-200E,U+2010-2011,U+204F,U+2E41,U+FB50-FDFF,U+FE70-FE74,U+FE76-FEFC}@font-face{font-family:'MutahText';font-style:normal;font-weight:700;font-display:block;src:url(data:font/woff2;base64,) format('woff2');unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD}@font-face{font-family:'MutahText';font-style:normal;font-weight:700;font-display:block;src:url(data:font/woff2;base64,) format('woff2');unicode-range:U+0600-06FF,U+0750-077F,U+0870-088E,U+0890-0891,U+0897-08E1,U+08E3-08FF,U+200C-200E,U+2010-2011,U+204F,U+2E41,U+FB50-FDFF,U+FE70-FE74,U+FE76-FEFC}";
main();
